use gost_sign_cms::verification::{VerificationError, verify_detached};
const CONTENT: &[u8] = include_bytes!("fixtures/synthetic-content.bin");
const CMS: &[u8] = include_bytes!("fixtures/synthetic-cades.der");
// Test-only d=1,k=2 signature generated by independent Python integer arithmetic.
// The certificate is synthetic/unsigned. No trust semantics are implied.
#[test]
fn synthetic_signature_verifies_and_binds_exact_binary_content() {
    assert_eq!(verify_detached(CONTENT, CMS), Ok(true));
    for index in 0..CONTENT.len() {
        let mut modified = CONTENT.to_vec();
        modified[index] ^= 1;
        assert_eq!(verify_detached(&modified, CMS), Ok(false));
    }
    assert_eq!(
        verify_detached(&CONTENT[..CONTENT.len() - 1], CMS),
        Ok(false)
    );
    let mut appended = CONTENT.to_vec();
    appended.push(0);
    assert_eq!(verify_detached(&appended, CMS), Ok(false));
}
#[test]
fn synthetic_signature_rejects_signature_changes_and_trailing_bytes() {
    let mut modified = CMS.to_vec();
    *modified.last_mut().expect("CMS octet") ^= 1;
    assert_eq!(verify_detached(CONTENT, &modified), Ok(false));
    let mut trailing = CMS.to_vec();
    trailing.push(0);
    assert_eq!(
        verify_detached(CONTENT, &trailing),
        Err(VerificationError::Malformed)
    );
}
